  players: [["Louis XVI", "Well-meaning but weak king"], ["Marie Antoinette", "Unpopular Austrian queen"], ["Necker", "Finance director whose 1781 report hid the debt"], ["Calonne", "Proposes a land tax on everyone (1786)"], ["Brienne", "Replaces Calonne and fails too"], ["Abbé Sieyès", "Writes What Is the Third Estate?"]],
  seq: [["1774", "Louis XVI restores the parlements"], ["1781", "Necker's misleading report"], ["1786", "Calonne's reform plan"], ["Feb 1787", "Assembly of Notables rejects it"], ["Jul 1788", "Estates General called"], ["Dec 1788", "Doubling the Third"], ["May 1789", "Estates General opens"], ["Jun 17, 1789", "National Assembly declared"], ["Jun 20, 1789", "Tennis Court Oath"], ["Jun 27, 1789", "Louis orders the estates to join"]],
  outcomes: ["The National Constituent Assembly now shares power with the king.", "Voting by order is dead, so the Third Estate dominates.", "Nobles who wanted power for themselves triggered a revolution against privilege."],
